def head(crumb_items, h1, lead, kicker=""):
    k = f'<span class="kicker">{esc(kicker)}</span>' if kicker else ""
    return f'<div class="pagehead"><div class="wrap">{crumbs_html(crumb_items).replace(chr(99)+"lass="+chr(34)+"crumbs wrap"+chr(34), "class=" + chr(34) + "crumbs" + chr(34))}{k}<h1>{esc(h1)}</h1><p class="lead">{esc(lead)}</p></div></div>'

def rng(id_, label, mn, mx, step, val, fmt="", suffix=""):
    f = f' data-fmt="{fmt}"' if fmt else ""
    s = f' data-suffix="{suffix}"' if suffix else ""
    return f'<div class="range f"><label for="{id_}">{label}: <output id="{id_}-o"></output></label><input type="range" id="{id_}" min="{mn}" max="{mx}" step="{step}" value="{val}"{f}{s}></div>'

def tool_page(slug, title, h1, lead, inputs, results, extra="", tool="emi", faqs=None, desc=None):
    path = f"/tools/{slug}/"
    faqs = faqs or []
    body = f'''{head([("Tools","/tools/"),(h1,None)], h1, lead, "Free tool")}
<section class="sec"><div class="wrap"><div class="tool"><div class="card raise">{inputs}</div><div class="result">{results}
<button class="btn btn-wa" id="send-wa" type="button" style="width:100%">{WA_SVG} Send this to NEXUS on WhatsApp</button><p class="fine" style="color:#9fb9d0;margin-top:8px">Indicative result. Not a loan offer. The lender decides after verification.</p></div></div>
{extra}
{('<h2 style="margin-top:40px">Frequently asked questions</h2>' + faq_html(faqs, True)) if faqs else ''}{note_box()}</div></section>{cta_band()}'''
    render(path, title, desc or trunc(lead, 158), body, [{"@context":"https://schema.org","@type":"WebApplication","name":h1,"applicationCategory":"FinanceApplication","operatingSystem":"Any","url":BASE+path,"offers":{"@type":"Offer","price":"0","priceCurrency":"INR"}}] + ([faq_ld(faqs)] if faqs else []),
           [("Tools", "/tools/"), (h1, None)], body_attr=f'data-tool="{tool}"', priority="0.8")

