def build_guides():
    cats = sorted(set(g["cat"] for g in GUIDES))
    cards = "".join(f'<a class="card prod" href="/guides/{g["slug"]}/"><span class="fine">{esc(g["cat"])}</span><h3>{esc(g["title"])}</h3><p>{esc(trunc(g["desc"],110))}</p><span class="more">Read →</span></a>' for g in GUIDES)
    body = f'''{head([("Guides",None)],"Loan Guides and Knowledge Centre","Plain-language guides on loans, credit scores, documents, rates, repayment and staying safe from fraud.","Learn")}<section class="sec"><div class="wrap"><div class="grid-3">{cards}</div></div></section>{cta_band()}'''
    render("/guides/","Loan Guides: Credit Score, EMI, Documents, Interest Rates & Safety | NEXUS","Free loan guides in simple language: how to apply, improve your credit score, understand APR, avoid fraud, and choose the right loan.",body,[{"@context":"https://schema.org","@type":"CollectionPage","name":"Loan Guides","url":BASE+"/guides/"}],[("Guides",None)],priority="0.8")
    for i, g in enumerate(GUIDES):
        rel = [x for x in GUIDES if x["slug"] != g["slug"]][i % 3:][:3]
        relh = "".join(f'<li><a href="/guides/{x["slug"]}/">{esc(x["title"])}</a></li>' for x in rel)
        body = f'''<div class="pagehead"><div class="wrap">{crumbs_html([("Guides","/guides/"),(trunc(g["title"],50),None)]).replace('class="crumbs wrap"','class="crumbs"')}<span class="kicker">{esc(g["cat"])}</span><h1>{esc(g["title"])}</h1><p class="lead">{esc(g["desc"])}</p><p class="fine">By the NEXUS Lending Partners team · Last updated {LAST_UPDATED}</p></div></div>
<div class="wrap layout"><article class="article">{g["body"]}<div class="note"><strong>Note:</strong> This guide is general information, not financial, legal or tax advice. Rules and rates change. Confirm with the lender or a qualified professional.</div><h2>Keep reading</h2><ul>{relh}</ul><h2>Explore loans</h2>{related_cards(["personal-loan","home-loan","business-loan"])}</article>
<aside class="side">{lead_form(None, title="Questions? Ask us on WhatsApp", extra_id="s")}<div class="card"><strong>Free tools</strong><ul><li><a href="/tools/emi-calculator/">EMI calculator</a></li><li><a href="/tools/loan-eligibility-calculator/">Eligibility calculator</a></li><li><a href="/tools/document-checklist/">Document checklist</a></li></ul></div></aside></div>{cta_band()}'''
        art = {"@context":"https://schema.org","@type":"Article","headline":g["title"],"description":g["desc"],"author":{"@type":"Organization","name":BRAND,"@id":ORG_ID},"publisher":{"@id":ORG_ID},"dateModified":"2026-11-13","datePublished":"2026-11-13","mainEntityOfPage":BASE+f"/guides/{g['slug']}/","image":BASE+"/assets/og-image.png"}
        render(f"/guides/{g['slug']}/", trunc(g["title"] + " | NEXUS", 68), trunc(g["desc"], 158), body, [art], [("Guides","/guides/"),(trunc(g["title"],50),None)], priority="0.7")

def build_company():
    # ABOUT
    body = f'''{head([("About",None)],"About NEXUS Lending Partners",TAGLINE,"Our story")}
<div class="wrap layout"><article class="article"><h2>Who we are</h2><p>NEXUS Lending Partners is a loan facilitation and advisory service based in Kukatpally, Hyderabad. We exist because borrowing in India is harder than it should be. There are hundreds of loan types, dozens of lenders, and fine print that hides the real cost.</p>
<p>We sit between the borrower and the lender as an honest connector. We explain, we prepare you, we match you to lenders whose criteria fit your profile, and we stay on after the loan is disbursed. We do not lend, and we do not take your money.</p>
<h2>What we believe</h2><div class="grid-2"><div class="card"><h3>Trust</h3><p>We say plainly that we are a facilitator and name the lender before you share documents.</p></div><div class="card"><h3>Transparency</h3><p>APR, fees, prepayment and our own commission model are explained in simple words.</p></div><div class="card"><h3>Right financial connections</h3><p>We match you to the lender whose rules fit your profile, rather than sending your documents everywhere.</p></div><div class="card"><h3>Long-term relationships</h3><p>Your first loan should lead to a better second one. We stay for your balance transfer, top-up and questions.</p></div></div>
<h2>What we do</h2><ul><li>Explain 100+ loan types in plain language</li><li>Check which type fits your need and profile</li><li>Give a precise document checklist so you apply once</li><li>Connect you with regulated banks and NBFCs</li><li>Support you through sanction, Key Fact Statement review and disbursal</li><li>Help you plan prepayment, balance transfer and consolidation</li></ul>
<h2>What we do not do</h2><ul><li>We do not lend, disburse or hold your money</li><li>We do not charge advance fees</li><li>We do not guarantee approval, rate or timeline</li><li>We do not ask for OTPs, PINs or passwords</li></ul>
<h2>Find us</h2><p>{esc(ADDRESS_LINE)}<br>Phone and WhatsApp: <a href="tel:{PHONE_TEL}">{PHONE_DISPLAY}</a><br>Email: <a href="mailto:{EMAIL}">{EMAIL}</a><br>Instagram: <a href="{INSTAGRAM}" rel="noopener me" target="_blank">@nexuslpofficial</a></p></article>
<aside class="side">{lead_form(None, title="Talk to us", extra_id="s")}</aside></div>{cta_band()}'''
    render("/about/","About NEXUS Lending Partners | Trusted Loan Partner in Hyderabad","NEXUS Lending Partners is a Hyderabad-based loan facilitation service built on trust, transparency, the right financial connections and long-term relationships.",body,[org_ld()],[("About",None)],priority="0.7")
    # WHY
    cmp_rows = [("Tells you plainly it is not the lender","Yes","Varies"),("Charges borrowers advance fees","Never","Be careful if asked"),("Explains APR, KFS and prepayment","Yes, in plain words","Often only the headline rate"),("Gives an exact document checklist","Yes","Sometimes"),("Shows commission model on request","Yes","Rarely"),("Support after disbursal","Yes","Rarely"),("Collects OTP, PIN, passwords","Never","Be careful if asked")]
    tbl = '<div class="tablewrap"><table class="t"><thead><tr><th>What matters</th><th>NEXUS</th><th>Typical unverified agent</th></tr></thead><tbody>' + "".join(f"<tr><td>{a}</td><td><strong>{b}</strong></td><td>{c}</td></tr>" for a, b, c in cmp_rows) + "</tbody></table></div>"
    body = f'''{head([("Why NEXUS",None)],"Why Borrowers Choose NEXUS","Honest guidance, clear costs and a team that stays with you after the loan.","Why NEXUS")}
<section class="sec"><div class="wrap"><div class="grid-3">{"".join(f'<div class="card">{icon(i)}<h3 style="margin-top:12px">{t}</h3><p style="margin:0;color:var(--muted)">{d}</p></div>' for i,t,d in [("shield","No advance fees","We never ask you to pay to get a loan approved. If anyone does in our name, tell us."),("eye","Plain-language clarity","APR, Key Fact Statement, moratorium, prepayment and foreclosure, explained simply."),("link","Right lender fit","We match your profile to lender criteria so you avoid pointless rejections."),("doc","Document readiness","A precise list per loan type means you apply once with everything matching."),("heart","Support after disbursal","Questions on EMIs, prepayment and balance transfer are welcome later too."),("check","WhatsApp-first","Ask, share updates and follow progress in a chat you already use.")])}</div>
<h2 style="margin-top:44px">How we compare</h2>{tbl}<p class="fine">Comparison is general and describes practices we recommend you look for in any loan intermediary.</p>{cta_band()}</div></section>'''
    render("/why-nexus/","Why Choose NEXUS Lending Partners | No Advance Fees, Transparent Loan Guidance","Why borrowers choose NEXUS: no advance fees, plain-language APR guidance, document readiness, right lender fit and support after disbursal.",body,None,[("Why NEXUS",None)],priority="0.6")
    # HOW
    hw = [("Tell us your need","Choose the loan type, amount and city on WhatsApp or our form. We do not ask for ID numbers or OTPs."),("We check the fit","We compare your profile with typical criteria of partner lenders and suggest the right loan type and lenders."),("Prepare documents","You get an exact checklist, so your file is complete the first time."),("Apply with the lender","You apply on the lender's secure channel. KYC, income and, where relevant, asset verification happen here."),("Review the sanction","Read the sanction letter and the Key Fact Statement. We help you understand APR, fees and prepayment."),("Disbursal and after-care","The lender pays you directly. We remain available for repayment, prepayment and your next need.")]
    body = f'''{head([("How it works",None)],"How NEXUS Works","Six clear steps from your first question to money in your account.","How it works")}<section class="sec"><div class="wrap" style="max-width:860px">{steps_html(hw)}<h2>What you pay us</h2><p>Nothing. Our assistance is free to borrowers. Partner lenders may pay us a commission when a loan is disbursed. Lenders charge their own fees, shown in your Key Fact Statement.</p><h2>Who decides approval</h2><p>The lender. We cannot guarantee approval, rate, amount or timeline.</p>{cta_band()}</div></section>'''
    render("/how-it-works/","How NEXUS Works: From Enquiry to Loan Disbursal in 6 Steps","See how NEXUS Lending Partners helps you choose a loan, prepare documents, apply with a regulated lender and get funds. No advance fees.",body,[{"@context":"https://schema.org","@type":"HowTo","name":"How to get a loan with NEXUS","step":[{"@type":"HowToStep","name":t,"text":d} for t,d in hw]}],[("How it works",None)],priority="0.6")
    # PARTNERS
    body = f'''{head([("Lending partners",None)],"Our Lending Partners and How We Choose Them","We connect borrowers with RBI-regulated banks, NBFCs and housing finance companies.","Partners")}<section class="sec"><div class="wrap" style="max-width:860px">
<h2>Types of lenders we work with</h2><ul><li><strong>Public and private sector banks:</strong> generally lower rates for strong profiles, stricter documentation.</li><li><strong>NBFCs:</strong> often faster and more flexible, sometimes at higher rates.</li><li><strong>Housing finance companies:</strong> specialists in home loans and loans against property.</li><li><strong>Fintech lending partners:</strong> digital journeys for small and quick loans, always through a regulated lender.</li></ul>
<h2>How we choose lenders</h2><ol><li>The lender is regulated by RBI. We verify this before working together.</li><li>Pricing and fees are disclosed clearly, including a Key Fact Statement.</li><li>Fair recovery practices and a working grievance process.</li><li>Good service quality and turnaround for borrowers.</li><li>Commission is never the only criterion. A better fit for you comes first.</li></ol>
<div class="note">Individual partner names and logos are shown only where we have the lender's written permission and an active arrangement. Where a lender has not agreed to be named, we will still tell you the lender's name before you share any document.</div>
<h2>Are you a lender?</h2><p>If you are a bank, NBFC or HFC interested in a partnership, write to <a href="mailto:{EMAIL}">{EMAIL}</a>.</p>{cta_band()}</div></section>'''
    render("/lending-partners/","Our Lending Partners: Banks, NBFCs and HFCs | NEXUS Lending Partners","How NEXUS selects RBI-regulated banks, NBFCs and housing finance companies as lending partners, and what that means for borrowers.",body,None,[("Lending partners",None)],priority="0.6")
    # PARTNER WITH US
    benefits = ["Clear, document-ready case handling","Transparent payout terms shared in writing before you start","Training on loan products, eligibility and compliance","Support on WhatsApp for case tracking","Zero investment to start","Ethical practice: no misstatement of income, no advance fees"]
    pf = lead_form(None, title="Tell us about yourself", sub="We will reply on WhatsApp with next steps for partnering.", cta="Send on WhatsApp", extra_id="p")
    body = f'''{head([("Partner with us",None)],"Partner with NEXUS: DSA, Agent and Connector Programme","Grow with a team that puts compliance and customer trust first.","Partners")}<div class="wrap layout"><article class="article"><h2>Who can partner</h2><ul><li>Freelance financial advisors and loan agents</li><li>CAs, tax consultants and accountants</li><li>Real estate and vehicle dealers who refer customers</li><li>Small business community leaders</li></ul><h2>What you get</h2>{ul(benefits)}<h2>Our standards</h2><p>Partners must follow lender policy, protect customer data, never charge borrowers unauthorised fees and never mis-state documents. Payout terms depend on the lender and are shared in writing.</p>{note_box()}</article><aside class="side">{pf}</aside></div>{cta_band()}'''
    render("/partner-with-us/","Become a Loan Partner: DSA & Agent Programme | NEXUS Lending Partners","Join NEXUS as a loan DSA, agent or connector in Hyderabad and across India. Ethical practice, transparent payouts and WhatsApp support.",body,None,[("Partner with us",None)],priority="0.6")

