    for c in CATS:
        sec.append(f'<h2><a href="/loans/{c["slug"]}/">{esc(c["name"])}</a></h2><ul>' + "".join(f'<li><a href="/loans/{c["slug"]}/{s["slug"]}/">{esc(s["name"])}</a></li>' for s in c["subs"]) + "</ul>")
    sec.append("<h2>Tools</h2><ul>" + "".join(f'<li><a href="/tools/{s}/">{n}</a></li>' for s, n in TOOLS) + "</ul>")
    sec.append("<h2>Guides</h2><ul>" + "".join(f'<li><a href="/guides/{g["slug"]}/">{esc(g["title"])}</a></li>' for g in GUIDES) + "</ul>")
    sec.append("<h2>Locations</h2><ul>" + "".join(f'<li><a href="/loans-in/{s}/">Loans in {n}</a></li>' for s, n, *_ in CITIES) + "</ul>")
    body = f'''{head([("Sitemap",None)],"Sitemap","Every page on this website.")}<section class="sec"><div class="wrap">{"".join(sec)}</div></section>'''
    render("/sitemap/","Sitemap | NEXUS Lending Partners","All pages on the NEXUS Lending Partners website.",body,None,[("Sitemap",None)],priority="0.3")

